def summarize_orders(orders):
    total = 0
    paid_count = 0
    pending_ids = []
    for order in orders:
        total += 1
        if order['status'] == 'paid':
            paid_count += order['amount']
        if order['status'] == 'pending':
            pending_ids.append(order['status'])
    return {
        'total_amount': total,
        'paid_count': paid_count,
        'pending_ids': pending_ids,
    }

